include!("common_fit.rs");
mod field{pub fn p()->u64{631}}
mod config{include!("field_config.rs");}
#[allow(dead_code)]mod good{include!("good.rs");include!("section_api.rs");include!("base_control.rs");}
fn prop(a:[u64;8],b:[u64;8])->bool{(0..8).all(|i|(0..8).all(|j|a[i]*b[j]%631==a[j]*b[i]%631))}
fn transform(m:&[[u64;8];8],x:[u64;8])->[u64;8]{std::array::from_fn(|i|m[i].iter().zip(x).fold(0,|z,(&a,b)|(z+a*b)%631))}
fn coord(j:&target::QuarticJacobian,s:&good::Sections,x:target::QClass,shift:target::QClass,overlap:&mut usize)->Option<[u64;8]>{let y=j.add_raw(&x,&shift);let a=target::graph_chart(j,y,false).and_then(|(u,v)|s.coords_chart(u,v,false));let b=target::graph_chart(j,y,true).and_then(|(u,v)|s.coords_chart(u,v,true));if let(Some(a),Some(b))=(a,b){assert!(prop(a,b),"chart_covariance");*overlap+=1;}a.or(b)}
fn main(){use hec_native_ic::{jac::Div,poly::Poly};use std::{fs,collections::HashSet};let a:Vec<_>=std::env::args().collect();let selected=fs::read_to_string(&a[1]).unwrap().trim().to_string();assert!(selected.starts_with("anchors")&&selected.len()==9);std::env::set_var("HEC_ANCHOR_I",selected.chars().nth(7).unwrap().to_string());std::env::set_var("HEC_ANCHOR_J",selected.chars().nth(8).unwrap().to_string());let input=std::path::Path::new(&a[1]).parent().unwrap().join(&selected).join("CALIBRATION.txt");let ns:Vec<u64>=fs::read_to_string(input).unwrap().split_whitespace().map(|s|s.parse().unwrap()).collect();let mut at=0;let mut ps=vec![];for _ in 0..2{let n=ns[at]as usize;at+=1;ps.push(Poly::from_coeffs(&ns[at..at+n]));at+=n;}assert_eq!(ns.len(),at+6);let pair:[[u64;3];2]=[ns[at..at+3].try_into().unwrap(),ns[at+3..].try_into().unwrap()];let base=Div{u:ps[0],v:ps[1]};let out=std::path::Path::new(&a[2]);assert!(!out.exists());fs::create_dir(out).unwrap();let src=source::Source::new();assert_eq!(src.mul_base(&base,59296481).u,Poly::one());config::install(config::discover(setup::qf()));let cfg=config::get();let j=target::QuarticJacobian::with_points(631,cfg.qf,cfg.points.clone()).unwrap();let sec=good::Sections::new();good::verify_canonical_line();let mut h=j.zero();for p in j.d_inf{let d=target::difference(&j,p,cfg.o);h=j.add_raw(&h,&j.add_raw(&d,&d));}for p in cfg.canonical{h=j.add_raw(&h,&j.neg_raw(&target::difference(&j,p,cfg.o)));}
let mut g2:HashSet<_>=[j.zero()].into_iter().collect();for i in 1..=16{let q=target::scalar(&j,target::difference(&j,cfg.points[i],cfg.points[0]),59296481);let old:Vec<_>=g2.iter().copied().collect();for x in old{for k in 0..4{g2.insert(j.add_raw(&x,&target::scalar(&j,q,k)));}}assert!(g2.len()<=4);}assert_eq!(g2.len(),4,"complete_target_two_primary");let h2=target::scalar(&j,h,59296481);assert_eq!(target::scalar(&j,h2,4),j.zero());let ho=j.add_raw(&h,&j.neg_raw(&h2));assert_eq!(target::scalar(&j,ho,59296481),j.zero());let mut roots:Vec<_>=g2.into_iter().filter(|q|j.add_raw(q,q)==h2).collect();roots.sort_by_key(|q|q.0);assert!(!roots.is_empty(),"no_rational_half_for_centering");let beta=j.add_raw(&target::scalar(&j,ho,29648241),&roots[0]);assert_eq!(j.add_raw(&beta,&beta),h);let old=target::scalar(&j,h,29648241);println!("CENTERING rational_halves={} two_primary_removed={} odd_only_formula_valid={} exact_double_identity=true",roots.len(),h2!=j.zero(),j.add_raw(&old,&old)==h);let shift=j.neg_raw(&beta);let image=target::scalar(&j,target::difference(&j,pair[0],pair[1]),4);assert_ne!(image,j.zero());assert_eq!(target::scalar(&j,image,59296481),j.zero());let mut overlap=0;let mut samples=vec![];for n in 1..=64{let Some(x)=src.eval(&src.mul_base(&base,n))else{println!("FIT_EXCLUDE n={n} source_chart");continue;};let Some(y)=coord(&j,&sec,target::scalar(&j,image,n),shift,&mut overlap)else{println!("FIT_EXCLUDE n={n} target_chart");continue;};samples.push((n,x,y));if samples.len()==16{break;}}assert_eq!(samples.len(),16,"fit_cap64");assert!(overlap>0);let mut rows=vec![];for(_,x,y)in&samples[..12]{for a in 0..8{for b in a+1..8{let mut r=vec![0;64];for k in 0..8{r[8*b+k]=y[a]*x[k]%631;r[8*a+k]=(631-y[b]*x[k]%631)%631;}rows.push(r);}}}let(rank,ker)=good::linear_kernel(rows,64);assert_eq!(rank,63);assert_eq!(ker.len(),1);let m:[[u64;8];8]=std::array::from_fn(|i|std::array::from_fn(|k|ker[0][8*i+k]));let(mrank,_)=good::linear_kernel(m.iter().map(|r|r.to_vec()).collect(),8);assert_eq!(mrank,8);for(n,x,y)in&samples{assert!(prop(transform(&m,*x),*y));println!("FIT_CONTROL n={n} training={} pass=true",samples[..12].iter().any(|s|s.0==*n));}let mut bad=m;let x=samples[12].1;let y=samples[12].2;let k=x.iter().position(|&a|a!=0).unwrap();let p=y.iter().position(|&a|a!=0).unwrap();bad[(p+1)%8][k]=(bad[(p+1)%8][k]+1)%631;assert!(!prop(transform(&bad,x),y));fs::write(out.join("MATRIX.txt"),m.iter().flatten().map(u64::to_string).collect::<Vec<_>>().join(" ")+"\n").unwrap();fs::write(out.join("CENTERING.txt"),format!("beta={:?}\nshift={:?}\n",beta.0,shift.0)).unwrap();println!("PASS F631_alignment=true selected={selected} rank=63 matrix_rank=8 training=12 withheld=4 chart_overlaps={overlap} corrupted_matrix_rejected=true clearing_multiplier=4 original_D1_B_images_or_DLP_verified=false");}
